+    // Process rows [row_start, row_end)
+    // Use i-k-j loop order for cache efficiency and vectorization potential
+    // C is not zeroed, so we must zero the relevant rows first
+    for (int i = row_start; i < row_end; ++i) {
+        std::memset(C + i * n, 0, n * sizeof(float));
+    }
